%}.qa-ledger__table th:nth-child(5){width:28%}.qa-ledger__table th:nth-child(6){width:10%}.qa-ledger__table th:nth-child(7){width:7%}}@media(max-width:767px){.qa-ledger__table{display:none}.qa-ledger__mobile{display:grid;margin:0;padding:0}.qa-ledger__mobile li{border-top:1px solid var(--ui-border);display:grid;gap:.55rem;list-style:none;padding:1rem 0}.qa-ledger__mobile-classification{color:var(--ui-text-muted);font-size:.78rem;margin:0}.qa-ledger__mobile :deep(button),.qa-ledger__mobile :deep(a[class*=button]){min-height:2.75rem}}
</style>
